import os
import base64
from openai import OpenAI

def vision_llm(system_msg, prompt_txt, image_path):

    client = OpenAI(
        api_key=os.getenv("NVIDIA_API_KEY2"),
        base_url="https://integrate.api.nvidia.com/v1"
    )

    # ---------------------------
    # Encode image correctly
    # ---------------------------
    with open(image_path, "rb") as img_file:
        image_base64 = base64.b64encode(img_file.read()).decode("utf-8")

    # detect extension properly
    ext = os.path.splitext(image_path)[1].replace(".", "")

    # ---------------------------
    # Messages
    # ---------------------------
    messages = [
        {"role": "system", "content": system_msg},
        {
            "role": "user",
            "content": [
                {"type": "text", "text": prompt_txt},
                {
                    "type": "image_url",
                    "image_url": {
                        "url": f"data:image/{ext};base64,{image_base64}"
                    }
                }
            ]
        }
    ]

    response = client.chat.completions.create(
        model="meta/llama-3.2-90b-vision-instruct",
        messages=messages,
        max_tokens=300,
        temperature=0.5
    )

    return response.choices[0].message.content

### Define the food image caption prompts
def image_caption_prompt_template(food_name):
    # system message → defines behavior
    image_caption_system_msg = f"""
You are a food image captioning assistant.

Your task:
- Describe the food shown in the image
- Focus specifically on the dish: "{food_name}"
- Keep the description clear and concise
- Mention visible ingredients, textures, and presentation
- Do NOT add unrelated details
"""

    # user prompt → actual instruction
    image_caption_prompt_txt = f"""
Describe the dish "{food_name}" shown in this image.

Include:
- Key ingredients you can see
- Appearance (color, texture)
- Presentation style

Keep it under 3-4 sentences.
"""

    return image_caption_system_msg, image_caption_prompt_txt


# ---------------------------
# Step 3.2: Get prompts
# ---------------------------
recipe1 = recipe_data[0]

system_msg, prompt_txt = image_caption_prompt_template(recipe1["name"])

img_path = f"synthetic_recipe_images/recipe{recipe1['id']}.png"

