print(response)

for i in range(len(recipe_data)):
    
    if (i + 1) % 5 == 0:
        print(f'{i+1} out of {len(recipe_data)} is done')

    # ---------------------------
    # Step 4.1: Get caption prompts
    # ---------------------------
    food_name = recipe_data[i]["name"]
    system_msg, prompt_txt = image_caption_prompt_template(food_name)

    # image path (handles png/jpg safely)
    img_path = None
    for ext in ["png", "jpg", "jpeg"]:
        temp_path = f"synthetic_recipe_images/recipe{recipe_data[i]['id']}.{ext}"
        if os.path.exists(temp_path):
            img_path = temp_path
            break

    # skip if image not found
    if img_path is None:
        print(f"Image not found for recipe {i}")
        recipe_data[i]["image_description"] = None
        continue

    # ---------------------------
    # Step 4.2: Get response
    # ---------------------------
    response = vision_llm(system_msg, prompt_txt, img_path)

    # ---------------------------
    # Save response
    # ---------------------------
    recipe_data[i]["image_description"] = response

print("ALL DONE!")

filename = 'augmented_food_recipe.json'
with open(filename, 'w', encoding='utf-8') as f:
    json.dump(recipe_data, f, indent=4)

