### Prompt template: caption images using review context
def review_context_image_caption_prompt_template(reviews):
    # reviews: text review from user

    ### Step 2.1: System prompt
    review_context_image_caption_system_msg = """
You are a multimodal food review analyst.

Your task:
- Look at the food image AND the user review text
- Generate a caption that combines both visual information and user sentiment
- Be accurate and only describe what is visible in the image
- Use the review to understand taste, quality, and experience
- Do NOT hallucinate ingredients not visible
"""

    ### Step 2.2: User prompt
    review_context_image_caption_prompt_txt = f"""
Generate a detailed caption for the food image.

User review:
{reviews}

Instructions:
- Describe the dish in the image
- Incorporate user sentiment (positive/negative feedback)
- Mention appearance, texture, and presentation
- Keep it 3–5 sentences
"""

    return review_context_image_caption_system_msg, review_context_image_caption_prompt_txt
print(user_review_data[0].keys())

import ast
import os
import requests
from tenacity import retry, stop_after_attempt, wait_exponential

### URL Request function with Retry
@retry(stop=stop_after_attempt(10), wait=wait_exponential(multiplier=1, min=1, max=10))
def get_data_with_retry(url):
    response = requests.get(url, timeout=5)
    response.raise_for_status()
    return response


### Start loop over user reviews
for i in range(len(user_review_data)):

    ### Step 3.1: Convert string → Python list
    review_images = ast.literal_eval(user_review_data[i]["images"])

    review_image_captions = []

    if len(review_images) > 0:

        for img_url in review_images:
            try:
                ### Step 3.2: Fetch image with retry
                image_data = get_data_with_retry(img_url)
                print("Success!")

            except Exception as e:
                print(f"All retries failed at url {img_url}:", e)
                continue

            # Save image temporarily
            image = image_data.content
            with open("review_image_placeholder.jpg", "wb") as img_file:
                img_file.write(image)

            ### Step 3.3: Generate caption using vision LLM
            system_msg, prompt_txt = review_context_image_caption_prompt_template(
                user_review_data[i]["text"]
            )

            caption = vision_llm(
                system_msg,
                prompt_txt,
                "review_image_placeholder.jpg"
            )

            review_image_captions.append(caption)

    ### Save captions into dataset
    user_review_data[i]["image_captions"] = review_image_captions

print("ALL DONE!")

filename = 'augmented_user_review.json'
with open(filename, 'w', encoding='utf-8') as f:
    json.dump(user_review_data, f, indent=4)